$inicio=date('Y-m-01');$fim=date('Y-m-t');$iAnt=date('Y-m-01',strtotime('first day of last month'));$fAnt=date('Y-m-t',strtotime('last day of last month'));
$receitas=cpTotalPeriodo($pdo,'receitas','data_receita',$usuarioId,$inicio,$fim);$despesas=cpTotalPeriodo($pdo,'despesas','data_despesa',$usuarioId,$inicio,$fim);$despesasAnt=cpTotalPeriodo($pdo,'despesas','data_despesa',$usuarioId,$iAnt,$fAnt);$resultado=$receitas-$despesas;$saldo=cpSaldoGeral($pdo,$usuarioId);$taxa=$receitas>0?round($resultado/$receitas*100,1):null;
