$radar=[];$varDesp=$despesasAnt>0?(($despesas-$despesasAnt)/$despesasAnt*100):null;if($varDesp!==null&&$varDesp>15)$radar[]=['nivel'=>'amarelo','titulo'=>'Gastos acima do ritmo','mensagem'=>'Suas despesas cresceram '.number_format($varDesp,1).'% em relação ao mês anterior.'];if($resultado<0)$radar[]=['nivel'=>'vermelho','titulo'=>'Mês no negativo','mensagem'=>'As despesas superam as receitas em '.formatarMoeda(abs($resultado)).'.'];if($limite!==null&&$despesas>$limite)$radar[]=['nivel'=>'vermelho','titulo'=>'Limite mensal ultrapassado','mensagem'=>'Você passou seu limite de gastos em '.formatarMoeda($despesas-$limite).'.'];if($cats){$totalC=array_sum(array_map(fn($x)=>(float)$x['total'],$cats));$top=$cats[0];$pct=$totalC>0?(float)$top['total']/$totalC*100:0;if($pct>=35)$radar[]=['nivel'=>'amarelo','titulo'=>'Gastos concentrados em '.$top['categoria'],'mensagem'=>$top['categoria'].' representa '.number_format($pct,0).'% das principais despesas do mês ('.formatarMoeda((float)$top['total']).').'];}if($receitas>0&&$resultado/$receitas>=.2)$radar[]=['nivel'=>'verde','titulo'=>'Boa folga no mês','mensagem'=>'Seu resultado positivo equivale a '.number_format($resultado/$receitas*100,0).'% das receitas atuais.'];
$stmt=$pdo->prepare("(SELECT 'receita' tipo,descricao,valor,data_receita data FROM receitas WHERE usuario_id=:a) UNION ALL (SELECT 'despesa' tipo,descricao,valor,data_despesa data FROM despesas WHERE usuario_id=:b) ORDER BY data DESC LIMIT 7");$stmt->execute(['a'=>$usuarioId,'b'=>$usuarioId]);$movs=$stmt->fetchAll();
$stmt=$pdo->prepare('SELECT titulo,valor_meta,valor_atual FROM metas WHERE usuario_id=:uid AND concluida=0 ORDER BY prazo IS NULL,prazo ASC LIMIT 3');$stmt->execute(['uid'=>$usuarioId]);$metas=$stmt->fetchAll();
